import React from "react";

export default function DashboardCard() {
    return (
        <>
        <div className="card">
            <div className="card-body">
                <h5 className="card-title">Dashboard</h5>
                <p className="card-text">Welcome to the Analytics Dashboard!</p>
            </div>
        </div>
        </>
    )
}
